    if (!hallAsked) { hallAsked = true; fetch('hall/index.json', { cache: 'no-store' }).then(r => r.json()).then(d => { hallCards = (d.cards || []).slice().sort((a, b) => a.maker ? -1 : b.maker ? 1 : String(b.issued).localeCompare(String(a.issued))); if (!Game.state.handle) render(); }).catch(() => { hallCards = []; }); }
